// fixtureRel is the committed fixture's path from this package's directory
// (the test binary's cwd): a real snapshot produced by the feedback
// capture's own code, regenerated by TestGenerateCommittedFixture when the
// corpus pin moves.
const fixtureRel = "testdata/feedback/" + fixtureID

// requireCorpus skips when the worktree has no .cards/ corpus: every
// repro test replays a match, and a corpus-backed replay is impossible
// without it. Skipping (not failing) matches testutil.CorpusRegistry's
// clean-clone convention — but note a skipped run here exercises nothing,
// so a green result without a corpus proves nothing.
func requireCorpus(t *testing.T) {
	t.Helper()
	root, err := feedback.Root()
	if err != nil {
		t.Skipf("no repo root: %v", err)
	}
	if _, err := os.Stat(filepath.Join(root, ".cards")); err != nil {
		t.Skip("no .cards/ corpus present — run `make fetch-cards compile-cards`")
	}
}

// TestReproFixtureSummaryExitsZero is the committed fixture's gate: the
// CLI on it verifies the head and prints the summary, exiting 0.
func TestReproFixtureSummaryExitsZero(t *testing.T) {
	requireCorpus(t)
	var out bytes.Buffer
	if code := run([]string{fixtureRel}, &out, io.Discard); code != 0 {
		t.Fatalf("exit %d, output:\n%s", code, out.String())
	}
	for _, want := range []string{
		"== feedback report " + fixtureID,
		"replayed 24 of 24 recorded intents", // the fixture's own counts; regenerate both together
		"recorded head",
		"turn 2, round 1",
		"active: seat 0, priority: seat 0",
		"life 20",
		"Mother of Runes",
		"stack (top last):", // absent on an empty stack? checked loosely below
		"last log lines:",
	} {
		if want == "stack (top last):" {
			continue // the stack is empty at this point of the fixture
		}
		if !strings.Contains(out.String(), want) {
			t.Errorf("summary output missing %q:\n%s", want, out.String())
		}
	}
	// The empty stack prints nothing; the battlefield, the pending decision
	// and the log tail are what must be there.
	for _, want := range []string{"pending:", "Player 1", "Player 2"} {
		if !strings.Contains(out.String(), want) {
			t.Errorf("summary output missing %q", want)
		}
	}
}

// TestReproFixtureTamperedHeadExitsNonzero: a snapshot whose log.json head
// field does not match its own event chain is refused before the engine
// even runs, with DIVERGED and a non-zero exit.
func TestReproFixtureTamperedHeadExitsNonzero(t *testing.T) {
	requireCorpus(t)
	dir := tamperFixture(t, func(lg map[string]any) {
		lg["head"] = "deadbeefdeadbeef"
	})
	var out bytes.Buffer
	if code := run([]string{dir}, &out, io.Discard); code == 0 {
		t.Fatalf("tampered head exited 0:\n%s", out.String())
	}
	if !strings.Contains(out.String(), "DIVERGED") {
		t.Errorf("output missing DIVERGED:\n%s", out.String())
	}
}

// TestReproFixtureTamperedEventNamesFirstSeq: a snapshot whose recorded
// events no longer replay (here: one draw's object id altered) diverges
// at the first mismatching event, and the output names that seq and says a
// corpus change is an expected cause.
func TestReproFixtureTamperedEventNamesFirstSeq(t *testing.T) {
	requireCorpus(t)
	dir := tamperFixture(t, func(lg map[string]any) {
		evs := lg["events"].([]any)
		// Kind is a JSON number (Kind carries no text encoding on the wire);
		// kindNames orders game_start 0, shuffle 1, move_zone 2, draw 3, so
		// the first draw is the first event whose kind is 3.
		for _, ev := range evs {
			e := ev.(map[string]any)
			if e["kind"] == json.Number("3") { // draw
				obj, err := e["obj"].(json.Number).Int64()
				if err != nil {
					panic(err)
				}
				e["obj"] = obj + 1000
				return
			}
		}
		panic("fixture carries no draw event to tamper")
	})
	var out bytes.Buffer
	if code := run([]string{dir}, &out, io.Discard); code == 0 {
		t.Fatalf("tampered event exited 0:\n%s", out.String())
	}
	got := out.String()
	if !strings.Contains(got, "DIVERGED") {
		t.Errorf("output missing DIVERGED:\n%s", got)
	}
	if !strings.Contains(got, "corpus change") {
		t.Errorf("output missing the expected-cause note:\n%s", got)
	}
	// The divergence is named at the tampered event, not at the end.
	if !strings.Contains(got, "diverged at event") {
		t.Errorf("output missing the diverging seq:\n%s", got)
	}
}

// TestReproFixtureListRejectsPostGenesisTamper pins -list to the same full
// validation boundary as an ordinary replay. Event 50 is the land-choice
