// TestEngineAtMatchesReplayToHeads pins the brief's equality gate: for a
// spread of intent counts, EngineAt's engine and a hand-rolled
// replay.ReplayTo over the same snapshot's (Log, Config) stand at the same
// head — the same replay by construction, not two code paths. The negative
// case is NOT tautological: EngineAt normalizes n<0 to len(Intents) itself
// (ReplayTo clamps negatives to genesis), so EngineAt(-1) is compared
// against the explicit full-intent ReplayTo — and asserted to actually be
// the capture point, not genesis.
func TestEngineAtMatchesReplayToHeads(t *testing.T) {
	requireCorpus(t)
	l, cfg, meta, err := feedback.Load(fixtureRel)
	if err != nil {
		t.Fatalf("load: %v", err)
	}
	full, err := replay.Replay(l, cfg)
	if err != nil {
		t.Fatalf("full replay: %v", err)
	}
	for _, n := range []int{0, 1, 7, meta.IntentCount - 1, meta.IntentCount} {
		e1 := feedback.EngineAt(t, fixtureRel, n)
		e2, err := replay.ReplayTo(l, cfg, n)
		if err != nil {
			t.Fatalf("ReplayTo(%d): %v", n, err)
		}
		if e1.L.Head() != e2.L.Head() || len(e1.L.Events) != len(e2.L.Events) {
			t.Errorf("n=%d: EngineAt head %s (%d events), ReplayTo head %s (%d events)",
				n, e1.L.Head(), len(e1.L.Events), e2.L.Head(), len(e2.L.Events))
		}
	}
	neg := feedback.EngineAt(t, fixtureRel, -1)
	if neg.L.Head() != full.L.Head() || len(neg.L.Events) != len(full.L.Events) {
		t.Errorf("EngineAt(-1) head %s (%d events), full replay head %s (%d events)",
			neg.L.Head(), len(neg.L.Events), full.L.Head(), len(full.L.Events))
	}
	if neg.L.Head() != meta.Head {
		t.Errorf("EngineAt(-1) head %s is not the capture point (recorded %s)", neg.L.Head(), meta.Head)
	}
}

// TestReproOnFreshSnapshot runs the whole product on a snapshot captured
// live by the feedback capture's own code in this test — not the committed
// fixture — so the loader cannot drift from the capture shape without this
// failing. The corpus pin coupling the committed fixture carries does not
// apply here: the capture and the replay run against the same corpus.
func TestReproOnFreshSnapshot(t *testing.T) {
	requireCorpus(t)
	advance, r := gatedFixtureRegistry(t)
	advance(12)
	dir := t.TempDir()
	captureSnapshotFiles(t, r, dir)

	var out bytes.Buffer
	if code := run([]string{dir}, &out, io.Discard); code != 0 {
		t.Fatalf("exit %d, output:\n%s", code, out.String())
	}
	// 21 -> 24 (2026-09-17): main's sacrifice-asks-its-player and
	// remembered/triggered-referents merges pose real asks this same opening
	// sequence did not before, so the same advance(12) gate count now
	// captures more total intents.
	//
	// 24 -> 25 (2026-09-17, later the same day): the capture point itself
	// became deterministic. gatedFixtureRegistry's advance used to return
	// after the last release WITHOUT waiting for that released decision's
	// burst to be applied, so the snapshot raced the match goroutine and
	// caught 24 or 25 recorded intents depending on scheduling (3/300 at
	// default procs here; both replays verified every time — only this
	// fixed-count assertion could tell). advance now waits for seat 0's
	// NEXT decision to reach the gate — the match parked inside Decide with
	// every earlier event emitted — and the count was stably 25 (150 events,
	// head 775a4dcd17aaf606; 200/200 at GOMAXPROCS=2).
	//
	// 25 -> 26 (2026-09-23, wt/cli-20260922T225141Z-e771720d): the CR 103.1
	// toss-winner ask (rules.NewStartingPlayerChoice + AskStartingPlayer)
	// adds one recorded intent at genesis on every hosted match — the
	// DecisionAsk + DecisionMade pair before the pregame rounds open — so
	// the same advance(12) gate count now captures 26 (152 events). The
	// committed fixture stays at its own recorded 24 (its log predates the
	// ask, so it still reconstructs through plain New); regenerate it and
	// its assertions together if it is ever re-recorded (REPRO_REGEN_FIXTURE).
	if !strings.Contains(out.String(), "replayed 26 of 26 recorded intents") {
		t.Errorf("fresh snapshot summary unexpected:\n%s", out.String())
	}
	out.Reset()
	if code := run([]string{"-list", dir}, &out, io.Discard); code != 0 {
		t.Fatalf("list exit %d, output:\n%s", code, out.String())
	}
}

// TestReproEmitTestSkeletonCompilesAndFailsOnTODO: -emit-test copies the
// snapshot into the target package's testdata and writes a test that
// compiles and fails only on its TODO. The target is a scratch package
// under the repo root (a real package the go tool builds), removed on
// cleanup.
func TestReproEmitTestSkeletonCompilesAndFailsOnTODO(t *testing.T) {
	requireCorpus(t)
	root, err := feedback.Root()
	if err != nil {
		t.Skipf("no repo root: %v", err)
	}
	scratch := filepath.Join(root, "zzrepro-emittest")
	t.Cleanup(func() { os.RemoveAll(scratch) })
	if err := os.MkdirAll(scratch, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(scratch, "doc.go"), []byte("package emittmp\n"), 0o644); err != nil {
		t.Fatal(err)
	}

	var out bytes.Buffer
	if code := run([]string{"-emit-test", "zzrepro-emittest", fixtureRel}, &out, io.Discard); code != 0 {
		t.Fatalf("emit exit %d, output:\n%s", code, out.String())
	}
	if _, err := os.Stat(filepath.Join(scratch, "testdata", "feedback", fixtureID, "match.json")); err != nil {
		t.Errorf("snapshot not copied: %v", err)
	}

	// The generated test is the target package's EXTERNAL test package —
	// feedback imports the engine tier, so an internal-package skeleton
	// would be an import cycle for any engine-side target. The declaration
	// (not the file name) is what makes it external.
	san := sanitize(fixtureID)
	raw, err := os.ReadFile(filepath.Join(scratch, "repro_feedback_"+san+"_test.go"))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(raw), "package emittmp_test") {
		t.Errorf("generated skeleton is not the external test package:\n%s", raw)
	}

	// The generated test compiles and fails on its TODO, not on load.
	cmd := exec.Command("go", "test", "./zzrepro-emittest", "-run", "TestFeedbackRepro20260914T120000Z_fb01")
	cmd.Dir = root
	raw2, err := cmd.CombinedOutput()
	if err == nil {
		t.Fatalf("generated test passed; it must fail on the TODO:\n%s", raw2)
	}
	if !strings.Contains(string(raw2), "TODO: assert the reported behaviour") {
		t.Fatalf("generated test failed for another reason:\n%s", raw2)
	}
}

// TestReproEmitTestIntoRulesCompilesAndFailsOnTODO probes the NATURAL
// emit-test target: an ENGINE package (the reported behaviour lives in
// rules/), where an internal-package skeleton would form
// rules -> feedback -> rules — an import cycle the go toolchain refuses at
// setup. The skeleton is the external test package, so emitting into a
// rules-shaped engine target must compile and fail only on the TODO.
//
// The target is a runtime CLONE of the rules package (its non-test sources
// copied verbatim into zzrepro-emitrules at the repo root, so the package
// is still named rules and every import stays inside the module), not the
// real rules/ directory. Writing the skeleton into the real rules dir made
// this probe a hazard to every other build of ./rules: a gate process
// killed between emit and cleanup left the skeleton (and its snapshot)
// behind, and the next module gate's probe then refused to emit ("already
// exists; not overwriting" -> exit 2 with a discarded stderr) while its
// cleanup deleted that stale file out from under a concurrently loading
// rules build ("open rules/repro_feedback_..._test.go: no such file or
// directory") — both seen in one gate run. A root-level scratch directory
// is never in `go test ./...`'s package list (enumerated before the tests
// run), and archtest's 32-bit build filters zzrepro-* out of its list, so
// nothing can race it or inherit residue. The cycle premise is asserted statically instead of by mutating
// the real tree.
func TestReproEmitTestIntoRulesCompilesAndFailsOnTODO(t *testing.T) {
	requireCorpus(t)
	root, err := feedback.Root()
	if err != nil {
		t.Skipf("no repo root: %v", err)
	}

	// Premise: feedback (which every skeleton imports) really does import
	// the engine tier's rules package — that import is the cycle an
	// internal-package skeleton would form, and the reason the emitted
	// declaration must carry the _test suffix.
	depsOut, err := exec.Command("go", "list", "-f", "{{join .Imports \"\\n\"}}",
		"github.com/adams-shaun/gorge/internal/testutil/feedback").CombinedOutput()
	if err != nil {
		t.Fatalf("go list feedback imports: %v\n%s", err, depsOut)
	}
	if !strings.Contains(string(depsOut), "github.com/adams-shaun/gorge/rules") {
		t.Fatalf("premise lost: internal/testutil/feedback no longer imports the rules package:\n%s", depsOut)
	}

	target := filepath.Join(root, "zzrepro-emitrules")
	t.Cleanup(func() { os.RemoveAll(target) })
	if err := os.MkdirAll(target, 0o755); err != nil {
		t.Fatal(err)
	}
	ents, err := os.ReadDir(filepath.Join(root, "rules"))
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range ents {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") || strings.HasSuffix(e.Name(), "_test.go") {
			continue
		}
		src, err := os.ReadFile(filepath.Join(root, "rules", e.Name()))
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(target, e.Name()), src, 0o644); err != nil {
			t.Fatal(err)
		}
	}

	san := sanitize(fixtureID)
	var out bytes.Buffer
	if code := run([]string{"-emit-test", "zzrepro-emitrules", fixtureRel}, &out, io.Discard); code != 0 {
		t.Fatalf("emit exit %d, output:\n%s", code, out.String())
	}
	raw, err := os.ReadFile(filepath.Join(target, "repro_feedback_"+san+"_test.go"))
	if err != nil {
		t.Fatalf("skeleton not written into the rules clone: %v", err)
	}
	if !strings.Contains(string(raw), "package rules_test") {
		t.Fatalf("skeleton emitted into the rules clone is not the external test package:\n%s", raw)
	}
	cmd := exec.Command("go", "test", "./zzrepro-emitrules", "-run", "^TestFeedbackRepro20260914T120000Z_fb01$")
	cmd.Dir = root
	res, err := cmd.CombinedOutput()
	if err == nil {
		t.Fatalf("emitted rules test passed; it must fail on the TODO:\n%s", res)
	}
	if !strings.Contains(string(res), "TODO: assert the reported behaviour") {
		t.Fatalf("emitted rules test failed for another reason:\n%s", res)
	}
}

// TestReproEmitTestRefusesOverwrite: a second emit at the same target is
// refused rather than clobbering a test someone may have filled in.
func TestReproEmitTestRefusesOverwrite(t *testing.T) {
	requireCorpus(t)
	root, err := feedback.Root()
	if err != nil {
		t.Skipf("no repo root: %v", err)
	}
	scratch := filepath.Join(root, "zzrepro-emittest2")
	t.Cleanup(func() { os.RemoveAll(scratch) })
	if err := os.MkdirAll(scratch, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(scratch, "doc.go"), []byte("package emittmp\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	var out bytes.Buffer
	if code := run([]string{"-emit-test", "zzrepro-emittest2", fixtureRel}, &out, io.Discard); code != 0 {
		t.Fatalf("first emit exit %d:\n%s", code, out.String())
	}
	// Simulate a filled-in test and a hand-refreshed snapshot: the refused
	// second emit must leave both byte-identical, not just exit non-zero.
	san := sanitize(fixtureID)
	testPath := filepath.Join(scratch, "repro_feedback_"+san+"_test.go")
	logPath := filepath.Join(scratch, "testdata", "feedback", fixtureID, "log.json")
	filledTest := []byte("package emittmp_test\n\n// filled in by hand\n")
	editedLog := []byte(`{"edited":"by hand"}`)
	if err := os.WriteFile(testPath, filledTest, 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(logPath, editedLog, 0o644); err != nil {
		t.Fatal(err)
	}
	out.Reset()
	if code := run([]string{"-emit-test", "zzrepro-emittest2", fixtureRel}, &out, io.Discard); code == 0 {
		t.Fatalf("second emit overwrote the first:\n%s", out.String())
	}
	if got, _ := os.ReadFile(testPath); !bytes.Equal(got, filledTest) {
		t.Errorf("refused emit rewrote the test file:\n%s", got)
	}
	if got, _ := os.ReadFile(logPath); !bytes.Equal(got, editedLog) {
		t.Errorf("refused emit rewrote the snapshot's log.json:\n%s", got)
	}
}

// TestReproEmitTestRejectsTamperedCapture: -emit-test verifies the complete
// capture before writing. A log.json whose head alone was corrupted exits
// non-zero with DIVERGED and creates neither the snapshot copy nor the
// skeleton.
func TestReproEmitTestRejectsTamperedCapture(t *testing.T) {
	requireCorpus(t)
	root, err := feedback.Root()
	if err != nil {
		t.Skipf("no repo root: %v", err)
	}
	scratch := filepath.Join(root, "zzrepro-emittest3")
	t.Cleanup(func() { os.RemoveAll(scratch) })
	if err := os.MkdirAll(scratch, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(scratch, "doc.go"), []byte("package emittmp\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	dir := tamperFixture(t, func(lg map[string]any) {
		lg["head"] = "deadbeefdeadbeef"
	})
	var out bytes.Buffer
	if code := run([]string{"-emit-test", "zzrepro-emittest3", dir}, &out, io.Discard); code == 0 {
		t.Fatalf("tampered capture emitted with exit 0:\n%s", out.String())
	}
	if !strings.Contains(out.String(), "DIVERGED") {
		t.Errorf("output missing DIVERGED:\n%s", out.String())
	}
	if _, err := os.Stat(filepath.Join(scratch, "testdata")); !os.IsNotExist(err) {
		t.Errorf("tampered emit created testdata (stat err %v)", err)
	}
	if _, err := os.Stat(filepath.Join(scratch, "repro_feedback_"+sanitize(fixtureID)+"_test.go")); !os.IsNotExist(err) {
		t.Errorf("tampered emit wrote the skeleton (stat err %v)", err)
	}
}

// TestReproEmitTestStripsTokenScriptsFromLiveCapture is the ruling's
// boundary for -emit-test on a LIVE capture: the source match.json carries
// the raw token script text (host.FeedbackMatch.Tokens), and the committed
// copy must NOT — Forge token scripts are GPL-3.0 and must never be
// committed. The emitted match.json must carry neither `tokens` nor
// `tokens_unread`, the exact text must be SYNced into the gitignored token
// directory keyed by the fixture id, and the emitted snapshot must still
// replay (resolving its tokens from that sync directory) to the recorded
// head — the round-trip that keeps the sync path honest.
func TestReproEmitTestStripsTokenScriptsFromLiveCapture(t *testing.T) {
	requireCorpus(t)
	root, err := feedback.Root()
	if err != nil {
		t.Skipf("no repo root: %v", err)
	}
	scratch := filepath.Join(root, "zzrepro-stripemittest")
	t.Cleanup(func() { os.RemoveAll(scratch) })
	if err := os.MkdirAll(scratch, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(scratch, "doc.go"), []byte("package striped\n"), 0o644); err != nil {
		t.Fatal(err)
	}

	// A live capture, not the committed fixture: match.json carries tokens.
	advance, r := gatedFixtureRegistry(t)
	advance(12)
	src := t.TempDir()
	captureSnapshotFiles(t, r, src)
	id := filepath.Base(src)
	// -emit-test syncs the stripped token text into the gitignored token
	// directory keyed by this fixture id; remove it on cleanup so the test
	// does not litter that directory with a per-run random id.
	syncDir, err := feedback.TokenSyncDir(id)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { os.RemoveAll(syncDir) })
	// The live capture must carry readable token TEXT, not merely a
	// `tokens_unread` list. The old substring check for `"tokens"` was
	// satisfied by that unread list, so a capture whose token source paths
	// pointed at a removed worktree passed here and only surfaced later.
	// decodeLiveCaptureTokens asserts nonempty text and zero unread stems.
	decodeLiveCaptureTokens(t, src)

	var out bytes.Buffer
	if code := run([]string{"-emit-test", "zzrepro-stripemittest", src}, &out, io.Discard); code != 0 {
		t.Fatalf("emit exit %d, output:\n%s", code, out.String())
	}

	emitted := filepath.Join(scratch, "testdata", "feedback", id, "match.json")
	emittedRaw, err := os.ReadFile(emitted)
	if err != nil {
		t.Fatalf("emitted match.json not found: %v", err)
	}
	if strings.Contains(string(emittedRaw), "tokens") {
		t.Errorf("emitted match.json still carries token script text:\n%.300s", emittedRaw)
	}

	// The exact script text went to the gitignored sync directory instead,
	// keyed by the fixture id.
	syncRaw, err := os.ReadFile(filepath.Join(syncDir, "tokens.json"))
	if err != nil {
		t.Fatalf("token sync directory missing: %v", err)
	}
	var synced map[string]string
	if err := json.Unmarshal(syncRaw, &synced); err != nil {
		t.Fatalf("sync tokens.json: %v", err)
	}
	if len(synced) == 0 {
		t.Fatalf("sync directory carried %d token scripts, the capture had more", len(synced))
	}

	// The emitted snapshot resolves its tokens from the sync directory and
	// must still replay to the recorded head — the stripped copy is not a
	// silent no-op.
	l, cfg, meta, err := feedback.Load(filepath.Join(scratch, "testdata", "feedback", id))
	if err != nil {
		t.Fatalf("load emitted snapshot: %v", err)
	}
	ene, err := replay.Replay(l, cfg)
	if err != nil {
		t.Fatalf("replay emitted snapshot: %v", err)
	}
	if got := ene.L.Head(); got != meta.Head {
		t.Errorf("emitted snapshot replayed head %q, recorded %q", got, meta.Head)
	}
}

// TestPrintSeatsShowsOpponentAuraOnItsHost: the view groups battlefields by
// controller, so an Aura seat 0 controls on seat 1's creature sits in seat
// 0's list while its host sits in seat 1's. The summary must print it on the
// host (naming its controller), and not drop it from both sections.
func TestPrintSeatsShowsOpponentAuraOnItsHost(t *testing.T) {
	players := []view.PlayerView{
		{ID: 0, Name: "Caster", Battlefield: []view.CardView{
			{ID: 10, Name: "Pacifism", AttachedTo: 20},
			{ID: 11, Name: "Plains"},
		}},
		{ID: 1, Name: "Target", Battlefield: []view.CardView{
			{ID: 20, Name: "Grizzly Bears", Power: 2, Toughness: 2},
			{ID: 21, Name: "Rancor", AttachedTo: 20},
		}},
	}
	var out bytes.Buffer
	printSeats(&out, players, false)
	got := out.String()
	if !strings.Contains(got, "  - Grizzly Bears (#20) 2/2") {
		t.Errorf("host line missing:\n%s", got)
	}
	if !strings.Contains(got, "    - Pacifism (#10) 0/0 (seat 0's)") {
		t.Errorf("opponent's Aura not rendered under its host with its controller:\n%s", got)
	}
	if !strings.Contains(got, "    - Rancor (#21) 0/0") {
		t.Errorf("own attachment not rendered under its host:\n%s", got)
	}
	// A standalone permanent line starts the line with exactly two spaces;
	// a nested attachment line carries four. Anchor on the newline so a
	// nested "    - Pacifism" cannot be mistaken for a standalone "  - "
	// line (its substring would otherwise match).
	if strings.Contains(got, "\n  - Pacifism") || strings.Contains(got, "\n  - Rancor") {
		t.Errorf("an attachment also printed as a standalone permanent:\n%s", got)
	}
	if !strings.Contains(got, "  - Plains (#11)") {
		t.Errorf("unattached permanent missing:\n%s", got)
	}
}

// TestPrintSeatsKeepsAttachmentWithMissingHost: an attachment whose host is
// not in the view still prints, naming the host id, instead of vanishing.
func TestPrintSeatsKeepsAttachmentWithMissingHost(t *testing.T) {
	players := []view.PlayerView{{ID: 0, Name: "Solo", Battlefield: []view.CardView{
		{ID: 10, Name: "Bonesplitter", AttachedTo: 99},
	}}}
	var out bytes.Buffer
	printSeats(&out, players, false)
	if !strings.Contains(out.String(), "- Bonesplitter (#10) 0/0, attached to #99 (not on the battlefield)") {
		t.Errorf("orphaned attachment not printed:\n%s", out.String())
	}
}

// TestPrintSeatsAttachmentFullDetail is the regression for the review
// finding that a nested attachment was flattened to a name: a tapped
// attachment with counters and damage lost its object id, P/T, tapped
// state, damage and counters, and two same-name attachments became
// indistinguishable. Each attached permanent must carry the full
// characteristics a standalone one would.
func TestPrintSeatsAttachmentFullDetail(t *testing.T) {
	players := []view.PlayerView{
		{ID: 0, Name: "Caster", Battlefield: []view.CardView{
			{ID: 10, Name: "Lightning Greaves", Power: 2, Toughness: 2, Tapped: true,
				Damage: 3, Counters: map[string]int32{"+1/+1": 2}, AttachedTo: 20},
		}},
		{ID: 1, Name: "Target", Battlefield: []view.CardView{
			{ID: 20, Name: "Grizzly Bears", Power: 2, Toughness: 2, Tapped: true},
			{ID: 21, Name: "Lightning Greaves", Power: 2, Toughness: 2, AttachedTo: 20},
		}},
	}
	var out bytes.Buffer
	printSeats(&out, players, false)
	got := out.String()
	if !strings.Contains(got, "    - Lightning Greaves (#10) 2/2, damage 3, tapped, counters +1/+1:2 (seat 0's)") {
		t.Errorf("tapped counter-bearing attachment lost detail:\n%s", got)
	}
	if !strings.Contains(got, "    - Lightning Greaves (#21) 2/2") {
		t.Errorf("same-name attachment not rendered by its own id:\n%s", got)
	}
	if !strings.Contains(got, "  - Grizzly Bears (#20) 2/2, tapped") {
		t.Errorf("host detail missing:\n%s", got)
	}
}

// tamperFixture copies the committed fixture into a temp dir and rewrites
// its log.json through edit.
func tamperFixture(t *testing.T, edit func(map[string]any)) string {
	t.Helper()
	dir := t.TempDir()
	for _, f := range []string{"match.json", "view.json", "report.json"} {
		raw, err := os.ReadFile(filepath.Join(fixtureRel, f))
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(dir, f), raw, 0o644); err != nil {
			t.Fatal(err)
		}
	}
	raw, err := os.ReadFile(filepath.Join(fixtureRel, "log.json"))
	if err != nil {
		t.Fatal(err)
	}
	var lg map[string]any
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber() // preserve the uint64 seed exactly while editing another field
	if err := dec.Decode(&lg); err != nil {
		t.Fatal(err)
	}
	edit(lg)
	out, err := json.Marshal(lg)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "log.json"), out, 0o644); err != nil {
		t.Fatal(err)
	}
	return dir
}
